      Date thisDeparture = sdf.parse(getTrip().getDepartureTime());
      Date thisArrival = sdf.parse(getTrip().getArrivalTime());
      Date otherDeparture = sdf.parse(trip.getDepartureTime());
      Date otherArrival = sdf.parse(trip.getArrivalTime());
      // Check if intervals overlap (allow adjacent boundaries)
